const express = require('express');
const { RateLimiterRedis } = require('rate-limiter-flexible');
const Redis = require('ioredis');
const twilio = require('twilio');

const app = express();
app.use(express.json());

const redis = new Redis(process.env.REDIS_URL);
const twilioClient = twilio(process.env.TWILIO_SID, process.env.TWILIO_AUTH_TOKEN);

const smsLimiter = new RateLimiterRedis({
  storeClient: redis,
  keyPrefix: 'rl_sms_otp',
  points: 3,
  duration: 3600
});

app.post('/api/v2/auth/send-sms-code', async (req, res) => {
  if (!req.user || !req.user.registeredPhone) {
    return res.status(401).json({ error: 'Authentication required with registered phone' });
  }

  // Use the verified phone number associated with the authenticated session
  const targetPhone = req.user.registeredPhone;

  try {
    await smsLimiter.consume(targetPhone);
  } catch (rejRes) {
    return res.status(429).json({ error: 'Too many OTP requests for your account' });
  }

  const otp = Math.floor(100000 + Math.random() * 900000).toString();
  await redis.set(`otp:${targetPhone}`, otp, 'EX', 300);

  await twilioClient.messages.create({
    body: `Your verification code is: ${otp}`,
    from: process.env.TWILIO_FROM,
    to: targetPhone
  });

  res.json({ success: true, message: 'OTP sent' });
});

app.listen(9004);
